def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    opponents = observation.get('opponent_position', [])
    resources = observation.get('resources', [])
    obstacles = set(tuple(obs) for obs in observation.get('obstacles', []))

    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])

    # Determine nearest resource
    res_target = None
    min_res_dist = float('inf')
    for r in resources:
        d = dist((px, py), r)
        if d < min_res_dist:
            min_res_dist = d
            res_target = r

    # Determine nearest opponent
    opp_target = None
    min_opp_dist = float('inf')
    for o in opponents:
        d = dist((px, py), o)
        if d < min_opp_dist:
            min_opp_dist = d
            opp_target = o

    # Decide current goal: gather resource if available, else avoid opponent
    goal = res_target if res_target and (min_res_dist <= min_opp_dist or not opp_target) else None

    # Possible moves
    moves = {
        'up':    (0, -1),
        'down':  (0, 1),
        'left':  (-1, 0),
        'right': (1, 0)
    }

    # Function to check move validity
    def can_move(dx, dy):
        nx, ny = px + dx, py + dy
        if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
            return True
        return False

    # Choose move
    for dx, dy in moves.values():
        nx, ny = px + dx, py + dy
        if can_move(dx, dy):
            if goal:
                # Move towards resource
                if (nx, ny) == goal:
                    return [dx, dy]
            else:
                # Avoid opponent
                if (nx, ny) != opp_target:
                    return [dx, dy]

    # No safe move found, stand still
    return [0, 0]
